// Verus program: extract imaginary parts from a vector of complex numbers.
//
// Each complex number is represented as a pair (real, imag).
// The function returns a new Vec<f64> where out[i] == val[i].1.

use vstd::prelude::*;

verus! {

fn imag(val: Vec<(f64, f64)>) -> (out: Vec<f64>)
    ensures
        // Same length as input
        out.len() == val.len(),

        // Pointwise: out[i] is the imaginary part of val[i]
        forall|i: int| 0 <= i < val.len() ==> out[i] == val[i].1,

        // If imaginary part is 0.0 then output is 0.0
        forall|i: int| 0 <= i < val.len() ==> (val[i].1 == 0.0f64 ==> out[i] == 0.0f64),

        // If the input complex number is not (0.0, 0.0), output is still imag part
        forall|i: int|
            0 <= i < val.len() ==>
                (((val[i].0 != 0.0f64) || (val[i].1 != 0.0f64)) ==> out[i] == val[i].1),
{
    let mut out: Vec<f64> = Vec::new();
    let mut i: usize = 0;

    while i < val.len()
        invariant
            // i stays in bounds
            0 <= i <= val.len(),
            // out is exactly the imag parts for the prefix processed so far
            out.len() == i,
            forall|j: int| 0 <= j < i ==> out[j] == val[j].1,
    {
        let pair = val[i];
        out.push(pair.1);
        i = i + 1;
    }

    out
}

} // verus!